body#layout .tbly-top-ad:before { content:"IKLAN ATAS HEADER"!important; }
body#layout .tbly-top-ad:after { content:"Tempel kode iklan pada gadget posisi yang dipilih. Pertahankan ID dan urutan gadget; slot yang kosong memakai tampilan bawaan tema."!important; }
body#layout .tbly-ads-config:before { content:"KONFIGURASI ADSENSE"!important; }
body#layout .tbly-ads-config:after { content:"Gunakan key=value per baris. publisher=ca-pub-... adalah publisher; slot=... untuk unit bawaan. Unit per posisi memakai top, left, right, nav, home, beforePost, middlePost, afterPost, sidebar, atau sidebarBottom."!important; }
body#layout .tbly-rail-left:before { content:"IKLAN SAMPING KIRI"!important; }
body#layout .tbly-rail-left:after { content:"Tempel kode iklan pada gadget posisi yang dipilih. Pertahankan ID dan urutan gadget; slot yang kosong memakai tampilan bawaan tema."!important; }
body#layout .tbly-rail-right:before { content:"IKLAN SAMPING KANAN"!important; }
body#layout .tbly-rail-right:after { content:"Tempel kode iklan pada gadget posisi yang dipilih. Pertahankan ID dan urutan gadget; slot yang kosong memakai tampilan bawaan tema."!important; }
body#layout .tbly-header:before { content:"HEADER DAN LOGO"!important; }
body#layout .tbly-header:after { content:"Gunakan gadget Header Blogger untuk judul dan gambar logo. Pengisian tetap melalui formulir native Blogger."!important; }
body#layout .tbly-menu:before { content:"MENU NAVIGASI"!important; }
body#layout .tbly-menu:after { content:"Satu tautan per baris: Nama|URL. Contoh News|/search/label/News. Kolom ikon opsional tidak ditampilkan pada menu utama."!important; }
body#layout .tbly-nav-ad:before { content:"IKLAN BAWAH NAVIGASI"!important; }
body#layout .tbly-nav-ad:after { content:"Tempel kode iklan pada gadget posisi yang dipilih. Pertahankan ID dan urutan gadget; slot yang kosong memakai tampilan bawaan tema."!important; }
body#layout .tbly-topics:before { content:"TOPIK TRENDING"!important; }
body#layout .tbly-topics:after { content:"Satu tautan per baris: Nama|URL. Contoh Teknologi|/search/label/Teknologi."!important; }
body#layout .tbly-main:before { content:"KONTEN UTAMA"!important; }
body#layout .tbly-main:after { content:"Urutan mengikuti demo: headline, iklan beranda, Berita Pilihan, Video, Sorotan, News, Bisnis, Foto, Showbiz, Bola, Global, Terkini, lalu artikel dan rekomendasi. Isi gadget blok dengan key=value per baris, misalnya source=label, label=News, count=5, start=1, type=list (setiap pasangan pada baris terpisah). JSON juga didukung; kosong memakai bawaan."!important; }
body#layout .tbly-main { clear:none!important; float:left!important; width:54%!important; min-width:220px!important; max-width:86%!important; margin-right:2%!important; }
body#layout .tbly-home:before { content:"BERANDA DAN KANAL"!important; }
body#layout .tbly-home:after { content:"Isi gadget blok dengan key=value per baris, misalnya source=label, label=News, count=5, start=1, type=list (setiap pasangan pada baris terpisah). JSON juga didukung; kosong memakai bawaan."!important; }
body#layout .tbly-recommendations:before { content:"REKOMENDASI ARTIKEL"!important; }
body#layout .tbly-recommendations:after { content:"Isi gadget blok dengan key=value per baris, misalnya source=label, label=News, count=5, start=1, type=list (setiap pasangan pada baris terpisah). JSON juga didukung; kosong memakai bawaan."!important; }
body#layout .tbly-sidebar:before { content:"SIDEBAR"!important; }
body#layout .tbly-sidebar:after { content:"Populer memakai formulir native Blogger; Pilihan Editor memakai format blok. Iklan HTML918 adalah slot paling bawah yang sticky pada publik. Isi gadget blok dengan key=value per baris, misalnya source=label, label=News, count=5, start=1, type=list (setiap pasangan pada baris terpisah). JSON juga didukung; kosong memakai bawaan."!important; }
body#layout .tbly-sidebar { clear:none!important; float:left!important; width:30%!important; min-width:220px!important; max-width:86%!important; margin-right:2%!important; }
body#layout .tbly-footer:before { content:"FOOTER"!important; }
body#layout .tbly-footer:after { content:"Informasi, kanal, media sosial, dan kredit mengikuti urutan footer demo. Tautan memakai satu baris Nama|URL; tambahkan |ikon pada kanal dan sosial bila diperlukan."!important; }
body#layout .tbly-footer-info:before { content:"INFORMASI FOOTER"!important; }
body#layout .tbly-footer-info:after { content:"Satu tautan per baris: Nama|URL. Contoh Redaksi|/p/redaksi.html."!important; }
body#layout .tbly-footer-bottom:before { content:"FOOTER BAWAH"!important; }
body#layout .tbly-footer-bottom:after { content:"Sosial memakai Nama|URL|ikon, contoh YouTube|https://youtube.com/|youtube. Kredit dapat diisi teks atau HTML sederhana."!important; }
body#layout .tbly-mobile-menu:before { content:"MENU HP DAN LAINNYA"!important; }
body#layout .tbly-mobile-menu:after { content:"Satu tautan per baris: Nama|URL|ikon. Contoh News|/search/label/News|newspaper-variant-outline. Informasi menu HP cukup Nama|URL."!important; }
body#layout .tbly-body-columns:before { content:"KONTEN DAN SIDEBAR"!important; }
body#layout .tbly-body-columns:after { content:"Konten utama di kiri dan sidebar di kanan mengikuti demo. Satu kolom: konten utama dahulu, lalu sidebar."!important; }
body#layout #liputBeforePost.tbly-group:before { content:"IKLAN SEBELUM ISI ARTIKEL"!important; }
body#layout #liputBeforePost.tbly-group:after { content:"Slot sebelum isi artikel. Tempel kode pada gadget HTML/JavaScript."!important; }
