/* TemaBlogger panel ringkas: bingkai hanya pada kelompok utama. */
body#layout .tbly-group:before { border-bottom:0!important; padding-bottom:0!important; margin-bottom:14px!important; }
body#layout .tbly-group .tbly-group { border:0!important; border-radius:0!important; background:transparent!important; box-shadow:none!important; padding:0!important; }
body#layout .tbly-group .tbly-group:before { font-size:14px!important; margin-bottom:10px!important; }
body#layout .tbly-group .tbly-group:after { display:none!important; }

div.script:
//
(function () {
  'use strict';
  var d = document, body = d.getElementById('postBody');
  if (d.body.id === 'layout' || !body || !d.body.classList.contains('page-post')) return;
  function section(id) { var n = d.getElementById(id); return n && n.dataset.lpAdMoved !== 'true' ? n : null; }
  function hideHolder(id) { var n = d.getElementById(id); if (n) n.hidden = true; }
  function banner(n) {
    var box = d.createElement('aside'); box.className = 'article-ad-holder lp-ad-article-banner';
    box.setAttribute('aria-label', 'Iklan'); box.appendChild(n); n.dataset.lpAdMoved = 'true'; return box;
  }
  var before = section('liputBeforePost'), middle = section('liputMidPost'), after = section('liputAfterPost');
  if (before) {
    var first = body.firstElementChild, beforeBox = banner(before);
    if (first && first.querySelector('img') && first.textContent.trim().length < 300) first.after(beforeBox);
    else body.before(beforeBox);
    hideHolder('lpBeforePostAd');
  }
  if (middle) {
    var cfg = d.querySelector('#adsConfig .config-source');
    var configCopy = cfg ? (cfg.content || cfg).cloneNode(true) : null;
    if (configCopy) Array.prototype.forEach.call(configCopy.querySelectorAll('br'), function (n) { n.replaceWith('\n'); });
    var configText = configCopy ? configCopy.textContent : '';
    var ordinary = /(?:^|\n)\s*parallax\s*=\s*0\s*(?:$|\n)/i.test(configText);
    var box = d.createElement('aside'); box.className = 'article-ad-holder lp-ad-parallax' + (ordinary ? ' lp-ad-ordinary' : '');
    box.setAttribute('aria-label', 'Iklan');
    var windowEl = d.createElement('div'); windowEl.className = 'lp-ad-window';
    var creative = d.createElement('div'); creative.className = 'lp-ad-creative';
    creative.appendChild(middle); windowEl.appendChild(creative); box.appendChild(windowEl);
    var caption = d.createElement('div'); caption.className = 'lp-ad-parallax-caption';
    caption.textContent = 'Scroll untuk lanjut membaca'; box.appendChild(caption);
    var candidates = Array.prototype.filter.call(body.children, function (n) {
      if (!/^(P|DIV|BLOCKQUOTE|UL|OL|H2|H3)$/.test(n.tagName)) return false;
      if (n.matches('.article-ad-holder,.inline-related,.tr-caption-container') || n.querySelector('img,iframe,video,.lp-ad-slot')) return false;
      var value = (n.textContent || '').trim();
      return value.length > 40 && !/^(Foto|Sumber|Credit|Ilustrasi|Keterangan foto)\s*[:.]/i.test(value);
    });
    var count = Number((window.SAE_CFG || {}).inAdAfterP) || 2;
    var anchor = candidates[Math.max(0, count - 1)];
    if (anchor) anchor.after(box); else body.appendChild(box);
    middle.dataset.lpAdMoved = 'true'; hideHolder('lpMiddlePostAd');
  }
  if (after) { body.after(banner(after)); hideHolder('lpAfterPostAd'); }
})();

