body.script:
//
(function () {
  'use strict';
  var OWNER_MODE = false;
  var d = document, root = d.documentElement, started = false, pending = false;
  function permitted() {
    var state = root.getAttribute('data-tb-domain-state');
    return d.body.id !== 'layout' && (OWNER_MODE || state === 'valid' || state === 'editor');
  }
  function query(s, n) { return (n || d).querySelector(s); }
  function all(s, n) { return Array.prototype.slice.call((n || d).querySelectorAll(s)); }
  function config() {
    var source = query('#adsConfig .config-source'), out = {};
    var clone = source ? (source.content || source).cloneNode(true) : null;
    if (clone) all('br', clone).forEach(function (n) { n.replaceWith('\n'); });
    (clone ? clone.textContent : '').split(/\r?\n/).forEach(function (line) {
      var i = line.indexOf('='); if (i > 0) out[line.slice(0, i).trim()] = line.slice(i + 1).trim();
    });
    return out;
  }
  var adConfig = {}, adOrigin = null;
  function syncPopularAd() {
    if (!d.body.classList.contains('page-home')) return;
    var popular = d.getElementById('PopularPosts1'), ad = d.getElementById('HTML916');
    if (!popular || !ad) return;
    if (!adOrigin) { adOrigin = d.createComment('liputspot sidebar ad origin'); ad.before(adOrigin); }
    if (window.innerWidth <= 767 && popular.closest('#mobilePopularSlot')) {
      if (popular.nextSibling !== ad) popular.after(ad);
    } else if (adOrigin.isConnected && adOrigin.nextSibling !== ad) adOrigin.after(ad);
  }
  function syncAnchorAds() {
    all('[data-lp-ad-anchor]').forEach(function (slot) {
      var anchor = d.getElementById(slot.dataset.lpAdAnchor);
      slot.hidden = !!(anchor && (anchor.hidden || anchor.dataset.emptyLabel === 'true'));
    });
  }
  function measure() {
    pending = false; if (!started) return;
    syncPopularAd(); syncAnchorAds();
    var content = query('.main-content'), rect = content && content.getBoundingClientRect();
    var width = root.clientWidth || window.innerWidth, gap = 24, rail = 160, edge = 12;
    var fits = !!(rect && width >= 1024 && window.innerHeight >= 350 && rect.left >= rail + gap + edge && width - rect.right >= rail + gap + edge);
    all('.lp-ad-rail').forEach(function (n) {
      n.classList.toggle('lp-rail-fits', fits);
      if (rect) n.style.left = (n.dataset.lpRail === 'left' ? rect.left - gap - rail : rect.right + gap) + 'px';
    });
    all('.lp-ad-parallax:not(.lp-ad-ordinary) .lp-ad-window').forEach(function (n) {
      var inner = query('.lp-ad-creative', n), r = n.getBoundingClientRect();
      if (inner) {
        inner.style.width = Math.min(300, r.width) + 'px';
        inner.style.left = (r.left + r.width / 2) + 'px';
      }
    });
    var header = d.getElementById('siteHeader');
    root.style.setProperty('--lp-sidebar-top', Math.max(12, (header ? header.offsetHeight : 100) + 12) + 'px');
    ensureAds();
  }
  function schedule() { if (!pending) { pending = true; requestAnimationFrame(measure); } }
  function ensureAds() {
    if (!permitted()) return;
    var publisher = (adConfig.publisher || '').trim();
    if (!/^ca-pub-\d{16}$/.test(publisher)) return;
    all('[data-lp-ad-position]').forEach(function (slot) {
      if (!permitted() || slot.dataset.lpManual === 'true' || slot.dataset.lpAdStatus || slot.closest('[hidden]') || !slot.getClientRects().length) return;
      var placeholder = query('[data-lp-placeholder="true"]', slot);
      if (!placeholder) return;
      var unit = (adConfig[slot.dataset.lpAdPosition] || adConfig.slot || '').trim();
      if (!/^\d{6,16}$/.test(unit)) return;
      if (!permitted()) return;
      if (!query('script[src*="pagead2.googlesyndication.com/pagead/js/adsbygoogle.js"]')) {
        var sdk = d.createElement('script'); sdk.async = true; sdk.crossOrigin = 'anonymous';
        sdk.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=' + publisher;
        d.head.appendChild(sdk);
      }
      var sizes = (slot.dataset.lpAdSize || '300x300').split('x').map(Number);
      var w = sizes[0], h = sizes[1];
      if (slot.dataset.lpAdPosition === 'top' && window.innerWidth <= 768) { w = 300; h = 585; }
      if (slot.closest('.lp-ad-ordinary')) { w = 300; h = 250; }
      var available = slot.clientWidth || w; w = Math.max(1, Math.min(w, available));
      var ad = d.createElement('ins'); ad.className = 'adsbygoogle';
      ad.style.display = 'block'; ad.style.width = w + 'px'; ad.style.maxWidth = '100%'; ad.style.height = h + 'px';
      ad.setAttribute('data-ad-client', publisher); ad.setAttribute('data-ad-slot', unit);
      if (!permitted()) return;
      placeholder.replaceWith(ad); slot.dataset.lpAdStatus = 'pending';
      try {
        if (!permitted()) return;
        (window.adsbygoogle = window.adsbygoogle || []).push({}); slot.dataset.lpAdStatus = 'configured';
      } catch (_) { slot.dataset.lpAdStatus = 'error'; }
    });
  }
  function start() {
    if (started || !permitted()) return;
    started = true; adConfig = config();
    all('[data-lp-close]').forEach(function (b) {
      b.addEventListener('click', function () {
        var target = d.getElementById(b.dataset.lpClose);
        if (target) {
          target.hidden = true; target.dataset.lpClosed = 'true';
          if (target.id === 'lpStickyBottom') d.body.classList.add('lp-bottom-closed');
        }
      });
    });
    addEventListener('scroll', schedule, {passive: true}); addEventListener('resize', schedule, {passive: true});
    var popularSlot = d.getElementById('mobilePopularSlot');
    if (popularSlot) new MutationObserver(schedule).observe(popularSlot, {childList: true});
    all('[data-lp-ad-anchor]').forEach(function (n) {
      var anchor = d.getElementById(n.dataset.lpAdAnchor);
      if (anchor) new MutationObserver(schedule).observe(anchor, {attributes: true, attributeFilter: ['hidden', 'data-empty-label']});
    });
    if ('ResizeObserver' in window) {
      var observer = new ResizeObserver(schedule), header = d.getElementById('siteHeader');
      if (header) observer.observe(header); var main = query('.main-content'); if (main) observer.observe(main);
    }
    measure();
  }
  function ready() {
    if (d.body.id === 'layout') return;
    start();
    if (!OWNER_MODE) new MutationObserver(function () { start(); schedule(); }).observe(root, {attributes: true, attributeFilter: ['data-tb-domain-state']});
  }
  if (d.readyState === 'loading') d.addEventListener('DOMContentLoaded', ready, {once: true}); else ready();
})();

